private fun money(v:Long)="Rp "+v.toString().reversed().chunked(3).joinToString(".").reversed()
private fun firstLetter(s:String)=s.trim().take(1).uppercase().ifBlank{"P"}

@Composable private fun PosApp() {
    var route by remember { mutableStateOf("pos") }
    var more by remember { mutableStateOf(false) }
    val tablet=LocalConfiguration.current.screenWidthDp>=600
    Row(Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background)) {
        if(tablet) SideBar(route){route=it}
        Box(Modifier.weight(1f).fillMaxHeight()) {
            when(route) {"home"->Home{route=it};"pos"->Sales();"products"->Products();"stock"->StockScreen();"customers"->Customers();"suppliers"->Suppliers();"payments"->Payments();"reports"->Reports();else->Settings()}
            if(!tablet) BottomBar(route,{if(it=="more")more=true else route=it})
        }
    }
    if(more) MoreDialog({more=false}){route=it;more=false}
}
private val mainNav=listOf("home","pos","products","stock")
private fun label(r:String)=when(r){"home"->"Beranda";"pos"->"Transaksi";"products"->"Produk";"stock"->"Stok";"customers"->"Pelanggan";"suppliers"->"Pemasok";"payments"->"Pembayaran";"reports"->"Laporan";else->"Pengaturan"}

