private suspend fun loadBusinessId():String=supabase.from("businesses").select{filter{eq("code",DEMO)}}.decodeList<Business>().first().id
private suspend fun loadContext():Triple<Business,Branch,Location>{val b=supabase.from("businesses").select{filter{eq("code",DEMO)}}.decodeList<Business>().first();val br=supabase.from("branches").select{filter{eq("business_id",b.id);eq("code","MAIN")}}.decodeList<Branch>().first();val loc=supabase.from("locations").select{filter{eq("branch_id",br.id);eq("code","STORE")}}.decodeList<Location>().first();return Triple(b,br,loc)}

@Composable private fun Sales(){var products by remember{mutableStateOf<List<Product>>(emptyList())};var prices by remember{mutableStateOf<List<ProductPrice>>(emptyList())};var cats by remember{mutableStateOf<List<Category>>(emptyList())};var units by remember{mutableStateOf<List<Unit>>(emptyList())};var customers by remember{mutableStateOf<List<Customer>>(emptyList())};var methods by remember{mutableStateOf<List<PaymentMethod>>(emptyList())};var cart by remember{mutableStateOf<List<Cart>>(emptyList())};var query by remember{mutableStateOf("")};var cat by remember{mutableStateOf("Semua")};var msg by remember{mutableStateOf<String?>(null)};var busy by remember{mutableStateOf(false)};val scope=rememberCoroutineScope();LaunchedEffect(Unit){try{val b=loadBusinessId();products=supabase.from("products").select{filter{eq("business_id",b);eq("is_active",true)}}.decodeList();prices=supabase.from("product_prices").select{}.decodeList();cats=supabase.from("categories").select{filter{eq("business_id",b);eq("is_active",true)}}.decodeList();units=supabase.from("units").select{filter{eq("business_id",b)}}.decodeList();customers=supabase.from("customers").select{filter{eq("business_id",b);eq("is_active",true)}}.decodeList();methods=supabase.from("payment_methods").select{filter{eq("business_id",b);eq("is_active",true)}}.decodeList()}catch(e:Exception){msg=e.message}};val filtered=products.filter{(cat=="Semua"||cats.firstOrNull{x->x.id==it.category_id}?.name==cat)&&(query.isBlank()||it.name.contains(query,true)||it.sku.contains(query,true))};val total=cart.sumOf{it.price*it.qty};val tablet=LocalConfiguration.current.screenWidthDp>=600;Page("Penjualan","Kasir • Toko Demo • Online"){msg?.let{if(it.startsWith("Gagal"))ErrorNotice(it)else Notice(it)};if(tablet)Row(Modifier.fillMaxWidth().weight(1f),horizontalArrangement=Arrangement.spacedBy(14.dp)){Catalog(filtered,cats,cat,query,prices,Modifier.weight(1.45f),{query=it},{cat=it}){p->addCart(p,prices,cart){cart=it}};CartBox(cart,total,Modifier.weight(.85f),{l->cart=cart.map{if(it.product.id==l.product.id)it.copy(qty=it.qty+1)else it}},{l->cart=cart.mapNotNull{if(it.product.id!=l.product.id)it else if(it.qty<=1)null else it.copy(qty=it.qty-1)}},{if(!busy){busy=true;scope.launch{msg=checkout(cart,customers.firstOrNull(),methods);if(msg?.startsWith("Tersimpan")==true)cart=emptyList();busy=false}}},busy)}else{Catalog(filtered,cats,cat,query,prices,Modifier.fillMaxWidth().weight(1f),{query=it},{cat=it}){p->addCart(p,prices,cart){cart=it}};if(cart.isNotEmpty())CartBox(cart,total,Modifier.fillMaxWidth(),{l->cart=cart.map{if(it.product.id==l.product.id)it.copy(qty=it.qty+1)else it}},{l->cart=cart.mapNotNull{if(it.product.id!=l.product.id)it else if(it.qty<=1)null else it.copy(qty=it.qty-1)}},{if(!busy){busy=true;scope.launch{msg=checkout(cart,customers.firstOrNull(),methods);if(msg?.startsWith("Tersimpan")==true)cart=emptyList();busy=false}}},busy)}}}
private fun addCart(p:Product,prices:List<ProductPrice>,cart:List<Cart>,set:(List<Cart>)->Unit){val price=prices.filter{it.product_id==p.id}.minByOrNull{it.min_qty}?.price?:p.current_cost;val old=cart.firstOrNull{it.product.id==p.id};set(if(old==null)cart+Cart(p,price,1)else cart.map{if(it.product.id==p.id)it.copy(qty=it.qty+1)else it})}
@Composable private fun Catalog(products:List<Product>,cats:List<Category>,selected:String,query:String,prices:List<ProductPrice>,modifier:Modifier,onQuery:(String)->Unit,onCat:(String)->Unit,onAdd:(Product)->Unit){Column(modifier,verticalArrangement=Arrangement.spacedBy(10.dp)){OutlinedTextField(query,onQuery,Modifier.fillMaxWidth(),placeholder={Text("Cari produk atau SKU")},singleLine=true);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(6.dp)){(listOf("Semua")+cats.map{it.name}).forEach{c->AssistChip(onClick={onCat(c)},label={Text(c)})}};LazyVerticalGrid(GridCells.Adaptive(145.dp),Modifier.fillMaxWidth().weight(1f),horizontalArrangement=Arrangement.spacedBy(8.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){items(products){p->val price=prices.firstOrNull{it.product_id==p.id}?.price?:p.current_cost;Card(Modifier.clickable{onAdd(p)},shape=RoundedCornerShape(12.dp)){Column(Modifier.padding(12.dp)){Box(Modifier.size(44.dp).background(MaterialTheme.colorScheme.primaryContainer,RoundedCornerShape(10.dp)),contentAlignment=Alignment.Center){Text(firstLetter(p.name),fontWeight=FontWeight.Bold,color=MaterialTheme.colorScheme.primary)};Spacer(Modifier.height(8.dp));Text(p.name,fontWeight=FontWeight.SemiBold,maxLines=2);Text(p.sku,style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(5.dp));Text(money(price),color=MaterialTheme.colorScheme.primary,fontWeight=FontWeight.Bold)}}}}}}
@Composable private fun CartBox(cart:List<Cart>,total:Long,modifier:Modifier,onPlus:(Cart)->Unit,onMinus:(Cart)->Unit,onPay:()->Unit,busy:Boolean){Card(modifier,shape=RoundedCornerShape(14.dp)){Column(Modifier.fillMaxSize().padding(14.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){Row(Modifier.fillMaxWidth()){Text("Keranjang",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));Text("${cart.sumOf{it.qty}} item",color=MaterialTheme.colorScheme.onSurfaceVariant)};HorizontalDivider();if(cart.isEmpty()){Spacer(Modifier.weight(1f));Text("Belum ada produk",Modifier.align(Alignment.CenterHorizontally),color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.weight(1f))}else{LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp)){items(cart){l->Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(l.product.name,fontWeight=FontWeight.SemiBold);Text(money(l.price),style=MaterialTheme.typography.labelSmall)};TextButton(onClick={onMinus(l)}){Text("−")};Text(l.qty.toString());TextButton(onClick={onPlus(l)}){Text("+")};Text(money(l.price*l.qty),fontWeight=FontWeight.SemiBold)}}};HorizontalDivider();Row(Modifier.fillMaxWidth()){Text("Total",fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));Text(money(total),style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)};Button(onClick=onPay,enabled=!busy,Modifier.fillMaxWidth().height(50.dp),shape=RoundedCornerShape(10.dp)){Text(if(busy)"Menyimpan..." else "BAYAR  ${money(total)}")};Text("Pembayaran demo dicatat PAID. Bukan konfirmasi QRIS provider.",style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}}}}
private suspend fun checkout(cart:List<Cart>,customer:Customer?,methods:List<PaymentMethod>):String{if(cart.isEmpty())return"Keranjang kosong";val(ctxB,br,loc)=loadContext();val method=methods.firstOrNull{it.code=="QRIS"}?:methods.firstOrNull()?:return"Metode pembayaran belum tersedia";val saleId=UUID.randomUUID().toString();val no="TRX-"+System.currentTimeMillis().toString().takeLast(8);val total=cart.sumOf{it.price*it.qty};val hpp=cart.sumOf{it.product.current_cost*it.qty};try{supabase.from("sales").insert(SaleInsert(saleId,ctxB.id,br.id,loc.id,customer?.id,no,"COMPLETED",total,total_amount=total,paid_amount=total,hpp_amount=hpp,margin_amount=total-hpp,notes="POS QRIS"));supabase.from("sale_items").insert(cart.map{SaleItemInsert(UUID.randomUUID().toString(),saleId,it.product.id,it.product.base_unit_id,it.product.sku,it.product.name,it.qty.toDouble(),unit_price=it.price,line_total=it.price*it.qty,hpp_unit=it.product.current_cost,hpp_total=it.product.current_cost*it.qty)});supabase.from("payments").insert(PaymentInsert(UUID.randomUUID().toString(),ctxB.id,br.id,saleId,method.id,"PAY-${no.removePrefix("TRX-")}",total));cart.forEach{line->val st=supabase.from("stock_balances").select{filter{eq("location_id",loc.id);eq("product_id",line.product.id)}}.decodeList<Stock>().firstOrNull();if(st!=null)supabase.from("stock_balances").update(StockUpdate(st.qty_base-line.qty)){filter{eq("location_id",loc.id);eq("product_id",line.product.id)}}};return"Tersimpan: $no • ${money(total)}"}catch(e:Exception){return"Gagal: ${e.message?:"database"}"}}

@Composable private fun Products(){var products by remember{mutableStateOf<List<Product>>(emptyList())};var unit by remember{mutableStateOf<Unit?>(null)};var pl by remember{mutableStateOf<PriceList?>(null)};var show by remember{mutableStateOf(false)};var name by remember{mutableStateOf("")};var sku by remember{mutableStateOf("")};var price by remember{mutableStateOf("")};var msg by remember{mutableStateOf<String?>(null)};val scope=rememberCoroutineScope();suspend fun reload(){val b=loadBusinessId();products=supabase.from("products").select{filter{eq("business_id",b);eq("is_active",true)}}.decodeList();unit=supabase.from("units").select{filter{eq("business_id",b);eq("code","PCS")}}.decodeList().firstOrNull();pl=supabase.from("price_lists").select{filter{eq("business_id",b);eq("is_default",true)}}.decodeList().firstOrNull()};LaunchedEffect(Unit){try{reload()}catch(e:Exception){msg=e.message}};Page("Produk","Katalog terhubung langsung ke Supabase",if(!show){@Composable{Button(onClick={show=true}){Text("+ Produk")}}}else null){msg?.let{if(it.startsWith("Gagal"))ErrorNotice(it)else Notice(it)};if(show)FormCard{OutlinedTextField(name,{name=it},Modifier.fillMaxWidth(),label={Text("Nama produk")},singleLine=true);OutlinedTextField(sku,{sku=it},Modifier.fillMaxWidth(),label={Text("SKU")},singleLine=true);OutlinedTextField(price,{price=it},Modifier.fillMaxWidth(),label={Text("Harga jual")},keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Number),singleLine=true);Button(onClick={scope.launch{try{val b=loadBusinessId();val u=unit?:throw IllegalStateException("Unit PCS tidak ditemukan");val p=price.toLongOrNull()?:throw IllegalArgumentException("Harga tidak valid");if(name.isBlank()||sku.isBlank())throw IllegalArgumentException("Nama dan SKU wajib");val id=UUID.randomUUID().toString();supabase.from("products").insert(ProductInsert(id,b,sku,name,name,null,u.id,current_cost=p,last_purchase_cost=p));val q=pl?:throw IllegalStateException("Price list tidak ditemukan");supabase.from("product_prices").insert(PriceInsert(UUID.randomUUID().toString(),q.id,id,u.id,price=p));reload();name="";sku="";price="";show=false;msg="Produk tersimpan"}catch(e:Exception){msg="Gagal: ${e.message}"}}}){Text("Simpan produk")}};LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(7.dp)){items(products){p->Row(Modifier.fillMaxWidth().background(Color.White,RoundedCornerShape(10.dp)).padding(12.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(40.dp).background(MaterialTheme.colorScheme.primaryContainer,RoundedCornerShape(9.dp)),contentAlignment=Alignment.Center){Text(firstLetter(p.name),fontWeight=FontWeight.Bold,color=MaterialTheme.colorScheme.primary)};Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text(p.name,fontWeight=FontWeight.SemiBold);Text(p.sku,style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.onSurfaceVariant)};TextButton(onClick={scope.launch{try{supabase.from("products").update(ActiveUpdate(false)){filter{eq("id",p.id)}};reload();msg="Produk dinonaktifkan"}catch(e:Exception){msg=e.message}}}){Text("Nonaktif")}}}}}}
}

@Composable private fun StockScreen(){var products by remember{mutableStateOf<List<Product>>(emptyList())};var stocks by remember{mutableStateOf<Map<String,Double>>(emptyMap())};var loc by remember{mutableStateOf<Location?>(null)};var msg by remember{mutableStateOf<String?>(null)};val scope=rememberCoroutineScope();suspend fun reload(){val b=loadBusinessId();val br=supabase.from("branches").select{filter{eq("business_id",b);eq("code","MAIN")}}.decodeList<Branch>().first();val l=supabase.from("locations").select{filter{eq("branch_id",br.id);eq("code","STORE")}}.decodeList<Location>().first();loc=l;products=supabase.from("products").select{filter{eq("business_id",b);eq("is_active",true)}}.decodeList();stocks=supabase.from("stock_balances").select{filter{eq("location_id",l.id)}}.decodeList<Stock>().associate{it.product_id to it.qty_base}};LaunchedEffect(Unit){try{reload()}catch(e:Exception){msg=e.message}};Page("Persediaan","Pantau dan sesuaikan stok toko"){msg?.let{ErrorNotice(it)};LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(7.dp)){items(products){p->val q=stocks[p.id]?:0.0;Row(Modifier.fillMaxWidth().background(Color.White,RoundedCornerShape(10.dp)).padding(12.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(p.name,fontWeight=FontWeight.SemiBold);Text(p.sku,style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.onSurfaceVariant)};Text("${q.toInt()} pcs",fontWeight=FontWeight.Bold,color=if(q<=p.min_stock)Color(0xFFD92D20) else MaterialTheme.colorScheme.onSurface);TextButton(onClick={scope.launch{try{val l=loc?:return@launch;supabase.from("stock_balances").update(StockUpdate(q+1)){filter{eq("location_id",l.id);eq("product_id",p.id)}};reload()}catch(e:Exception){msg=e.message}}}){Text("+1")}}}}}}

